#include <iostream>
#include <mutex>
#include <thread>
#include <vector>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<long long> values;
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        values.push_back(value);
    }
    std::mutex guard;
    long long total = 0;
    int half = n / 2;
    std::thread worker([&values, half, &guard, &total]() {
        for (int i = 0; i < half; i++) {
            std::lock_guard<std::mutex> locked(guard);
            total += values[static_cast<std::size_t>(i)];
        }
    });
    for (int i = half; i < n; i++) {
        std::lock_guard<std::mutex> locked(guard);
        total += values[static_cast<std::size_t>(i)];
    }
    worker.join();
    std::cout << total << std::endl;
    return 0;
}
